mapper.select:
SELECT hp.person_key AS person_key, hp.employee_no AS employee_no, hp.name_ko AS name_ko, hp.name_en AS name_en, hp.profile_photo_url AS profile_photo_url, hp.dept_cd AS dept_cd, d.dept_nm AS dept_name, hp.grade_code AS grade_code, grade.code_name AS grade_name, hp.position_code AS position_code, position.code_name AS position_name, hp.employment_type_code AS employment_type_code, employment.code_name AS employment_type_name, hp.service_status_code AS service_status_code, status.code_name AS service_status_name, hp.hire_date AS hire_date FROM hrm_person hp LEFT JOIN hrm_org_dept d ON hp.dept_cd = d.dept_cd AND d.use_yn = 'Y' LEFT JOIN com_code grade ON hp.grade_code = grade.code AND grade.parent_code = '102' AND grade.use_yn = 'Y' LEFT JOIN com_code position ON hp.position_code = position.code AND position.parent_code = '103' AND position.use_yn = 'Y' LEFT JOIN com_code employment ON hp.employment_type_code = employment.code AND employment.parent_code = '104' AND employment.use_yn = 'Y' LEFT JOIN com_code status ON hp.service_status_code = status.code AND status.parent_code = '101' AND status.use_yn = 'Y'
AND (hp.name_ko ILIKE '%' || #{condition.keyword} || '%' OR hp.employee_no ILIKE '%' || #{condition.keyword} || '%' OR hp.name_en ILIKE '%' || #{condition.keyword} || '%')
AND hp.dept_cd = #{condition.deptCd} AND hp.grade_code = #{condition.gradeCode} AND hp.position_code = #{condition.positionCode} AND hp.employment_type_code = #{condition.employmentTypeCode} AND hp.service_status_code = #{condition.serviceStatusCode}
ORDER BY hp.employee_no LIMIT #{condition.limit} OFFSET #{condition.offset}

SELECT COUNT(*)
FROM hrm_person hp


        AND (hp.name_ko ILIKE '%' || #{condition.keyword} || '%'
             OR hp.employee_no ILIKE '%' || #{condition.keyword} || '%'
             OR hp.name_en ILIKE '%' || #{condition.keyword} || '%')

    AND hp.dept_cd = #{condition.deptCd}
    AND hp.grade_code = #{condition.gradeCode}
    AND hp.position_code = #{condition.positionCode}
    AND hp.employment_type_code = #{condition.employmentTypeCode}
    AND hp.service_status_code = #{condition.serviceStatusCode}
